//       x2[i0] += A[0][i0]*y_2[0] + A[1][i0]*y_2[1] + ... + A[N-1][i0]*y_2[N-1]
//
//     Rewritten: for each fixed j0
//       x2[j0] is updated once per i in increasing order 0..N-1 with
//       A[i][j0]*y_2[i].  Thus the sequence of additions to each
//       x2[k] is identical: (A[0][k]*y_2[0]), (A[1][k]*y_2[1]), ...,
//       preserving floating‑point accumulation order.
//
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// View of y_1 as a vector over 'j' for direct y_1[j] access.
	// We only need this for the first part; for y_2 we keep the original
	// 'i' dimension, since in the optimized second part we index it by 'i'.
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();

#pragma scop
	// ---------------------------------------------------------------------
	// First part:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// We iterate rows of A (dimension 'i') and for each row accumulate
	// into a scalar register before writing x1[i] back once.
	// This improves cache and register usage and is vectorization‑friendly.
	// ---------------------------------------------------------------------
	noarr::traverser(A, y_1_j).template for_dims<'i'>([&](auto trav_i) {
		// trav_i: traverser with current 'i' fixed, iterating over 'j'
		auto state_i = trav_i.state();   // contains only dimension 'i'

		// Load current x1[i] into a register accumulator
		num_t acc = x1[state_i];

		// Inner loop over 'j' (contiguous in memory for A and y_1_j)
		trav_i.for_each([&](auto state_ij) {
			acc += A[state_ij] * y_1_j[state_ij];
		});

		// Store the accumulated result back once per i
		x1[state_i] = acc;
	});

	// ---------------------------------------------------------------------
	// Second part (rewritten form):
	//
	// Original:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// Rewritten (algebraically equivalent, same accumulation order):
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x2[j] = x2[j] + A[i][j] * y_2[i];
	//
	// We traverse A in its natural (row‑major) order: 'i' outer, 'j' inner.
	// For each fixed i, we reuse y_2[i] and update the whole x2 vector.
	// ---------------------------------------------------------------------
	noarr::traverser(A, y_2).template for_dims<'i'>([&](auto trav_i) {
		// trav_i: traverser with current 'i' fixed, iterating over 'j'
		auto state_i = trav_i.state();   // contains only dimension 'i'

		// Cache y_2[i] for this row of A
		num_t yi = y_2[state_i];

		// For each column j: x2[j] += A[i][j] * yi
		trav_i.for_each([&](auto state_ij) {
			// Extract j from the joint state
			auto j = noarr::get_index<'j'>(state_ij);

			// x2 is indexed by dimension 'i', so we build a state with 'i' = j
			auto state_j = noarr::idx<'i'>(j);

			x2[state_j] += A[state_ij] * yi;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// common length proto-structure for all dimensions
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);

	// initialize data
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination), if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
